WITH old_values AS (
    SELECT price as oldprice, stockquantity as oldstock FROM products WHERE productid = @ProductId
),
do_update AS (
    UPDATE products SET name = @Name, description = @Description, price = @Price, stockquantity = @StockQuantity, modifieddate = NOW() WHERE productid = @ProductId
),
log_change AS (
    INSERT INTO producthistory (productid, action, oldprice, newprice, oldstock, newstock, actiondate) SELECT @ProductId, 'UPDATE', ov.oldprice, @Price, ov.oldstock, @StockQuantity, NOW() FROM old_values ov
)
UPDATE productstats SET averageprice = (averageprice * totalproducts - (SELECT oldprice FROM old_values) + @Price) / totalproducts, lastupdated = NOW() WHERE statid = 1

