    SELECT price as oldprice, stockquantity as oldstock FROM products WHERE productid = @ProductId
),
log_deletion AS (
    INSERT INTO producthistory (productid, action, oldprice, newprice, oldstock, newstock, actiondate) SELECT @ProductId, 'DELETE', ov.oldprice, NULL, ov.oldstock, NULL, NOW() FROM old_values ov
),
do_delete AS (
    DELETE FROM products WHERE productid = @ProductId
)
UPDATE productstats SET totalproducts = totalproducts - 1, averageprice = CASE WHEN totalproducts > 1 THEN (averageprice * totalproducts - (SELECT oldprice FROM old_values)) / (totalproducts - 1) ELSE 0 END, lastupdated = NOW() WHERE statid = 1

